python - <<'PY'
import sys, dis, json
import pytest
from telegram._utils.files import parse_file_input

TARGET_CODE = parse_file_input.__code__

# Map bytecode offset -> (opname, argval, line)
instrs = list(dis.get_instructions(parse_file_input))
offset_map = {}
cur_line = TARGET_CODE.co_firstlineno
for ins in instrs:
    if ins.starts_line is not None:
        cur_line = ins.starts_line
    offset_map[ins.offset] = (ins.opname, ins.argval, cur_line)

param_def_lines = {
    "file_input": 97,
    "tg_type": 98,
    "filename": 99,
    "attach": 100,
    "local_mode": 101,
}

pair_set = set()
state_by_frame = {}


def tracer(frame, event, arg):
    if event == "call":
        if frame.f_code is TARGET_CODE:
            frame.f_trace_opcodes = True
            state_by_frame[id(frame)] = dict(param_def_lines)
            return tracer
        return None

    if frame.f_code is not TARGET_CODE:
        return tracer

    fid = id(frame)
    defs = state_by_frame.get(fid)
    if defs is None:
        defs = dict(param_def_lines)
        state_by_frame[fid] = defs

    if event == "opcode":
        opname, argval, line = offset_map.get(frame.f_lasti, (None, None, None))
        if opname == "LOAD_FAST":
            var = argval
            if var in defs and line is not None:
                pair_set.add((var, defs[var], line))
        elif opname == "STORE_FAST":
            var = argval
            if line is not None:
                defs[var] = line
    elif event == "return":
        state_by_frame.pop(fid, None)

    return tracer

sys.settrace(tracer)
try:
    rc = pytest.main(["-q", "tests/_utils/test_files.py", "-k", "parse_file_input"])
finally:
    sys.settrace(None)

pairs = [
    {"variable": v, "def_line": d, "use_line": u}
    for (v, d, u) in sorted(pair_set, key=lambda t: (t[0], t[1], t[2]))
]
print("PYTEST_RC", rc)
print(json.dumps(pairs, indent=2))
PY

